class NotesApp : Application() {
    // Long-lived: built once with the Application context, never an Activity.
    val database by lazy { NotesDatabase.create(applicationContext) }
}

// Leak: a singleton that keeps a screen alive after it closes.
// object Cache { lateinit var activity: Activity }   // never do this

class SearchViewModel(private val saved: SavedStateHandle, private val repo: ProductRepository) : ViewModel() {
    val query = saved.getStateFlow("query", "")          // back after process death
    private val _results = MutableStateFlow<List<Product>>(emptyList())
    val results = _results.asStateFlow()                // reloaded from the query when needed

    fun onQueryChange(text: String) {
        saved["query"] = text
        viewModelScope.launch { _results.value = repo.search(text) }
    }
}

@Composable
fun Filters() {
    var expanded by remember { mutableStateOf(false) }        // fine to lose on rotation
    var onlyInStock by rememberSaveable { mutableStateOf(true) } // the user expects it to stay
}

fun Context.sendEmail(to: String, subject: String) {
    val intent = Intent(Intent.ACTION_SENDTO).apply {
        data = Uri.parse("mailto:")                       // only email apps
        putExtra(Intent.EXTRA_EMAIL, arrayOf(to))
        putExtra(Intent.EXTRA_SUBJECT, subject)
    }
    try {
        startActivity(intent)
    } catch (e: ActivityNotFoundException) {
        Toast.makeText(this, "No email app found", Toast.LENGTH_SHORT).show()
    }
}

fun Context.openMap(lat: Double, lng: Double, label: String) =
    runCatching { startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("geo:$lat,$lng?q=$lat,$lng($label)"))) }

@Composable
fun ProfilePhoto() {
    var photo by rememberSaveable { mutableStateOf<Uri?>(null) }
    val pickPhoto = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        photo = uri                                        // null when the user cancels
    }
    Column {
        photo?.let { AsyncImage(model = it, contentDescription = "Profile photo") }
        Button(onClick = {
            pickPhoto.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))
        }) { Text("Choose photo") }
    }
}

